function sendJoin(join) {
  // Admin permission persists across (re)joins (27/11/2026, item 17):
  // the stored code goes first so the server holds it as a pending flag
  // and applies it when the join lands. This covers a manual rejoin on
  // the same socket (leave -> join), where onOpen does not fire. On a
  // reconnect onOpen already sent it — sending it twice is harmless,
  // the server just re-sets the same flag.
  if (savedAdminCode) socket.send({ t: 'admin', code: savedAdminCode });
  if (join.solo) socket.send({ t: 'solo', name: join.name, cls: join.cls || 'rifleman', grenades: join.grenades !== false, session: tabSessionId });
  else socket.send({ t: 'join', name: join.name, team: join.team, session: tabSessionId });
}
