// ---------------------------------------------------------------------------
// Main loop
// ---------------------------------------------------------------------------

const clock = new THREE.Clock();
let lastSizeSync = 0;

// Bird's-eye height (27/11/2026, post-v41 item 25 — the framing rule):
// the whole map must fit end to end, start and end points included
// (both teams' spawn zones and the objective), so the height is
// computed from the current layout's bounds, the screen aspect and
// the spectating field of view — not the fixed 55 m, which showed
// only a strip of a 124 m street. The spectating FOV is 75°
// (updateViewmodel enforces it while spectating) and the camera
// looks straight down, so the visible world height is 2·h·tan(37.5°)
// and the visible width is that times the aspect; the height is the
// larger of the two fits. The bounds are padded 4 m a side so the
// fence sits inside the frame with room to spare. Landscape
// 844×390: ~86 m on the small map, ~91 m on the large; portrait
// needs more (the width fit binds), and the formula covers it.
function birdEyeHeight() {
  const b = curLayout.bounds;
  const halfTan = Math.tan((75 / 2) * Math.PI / 180);
  const hZ = (b.z1 - b.z0 + 8) / (2 * halfTan);
  const hX = (b.x1 - b.x0 + 8) / (2 * halfTan * camera.aspect);
  return Math.max(hZ, hX);
}

function loop() {
  requestAnimationFrame(loop);
  if (!threeReady) return;
  const dt = Math.min(clock.getDelta(), 0.05);
  const now = performance.now();
  // Semi-auto: consume a queued FIRE press every frame, even when the
  // player is dead or spectating — a press then is discarded, never
  // fired late on the next round. The machine gunner is full-auto:
  // holding FIRE keeps firing (paced by tryFire's interval).
  const firePressed = controls.takeFirePress()
    || (myClass === 'gunner' && controls.fireHeld);

  // Backstop: re-sync the renderer size twice a second, so a canvas stuck
  // at a stale size (iOS rotation) heals even if no event fires.
  // Time-based, not frame-based: a throttled tab still heals promptly.
  if (now - lastSizeSync > 500) {
    lastSizeSync = now;
    window.__syncRendererSize?.();
    const dbg = window.__sizeDebug;
    if (dbg && renderer && camera) {
      const c = $('scene-container');
      const cv = renderer.domElement;
      dbg.textContent =
        `container ${c.clientWidth}x${c.clientHeight}\n` +
        `canvas ${cv.style.width} x ${cv.style.height} (buf ${cv.width}x${cv.height})\n` +
        `inner ${window.innerWidth}x${window.innerHeight} dpr ${window.devicePixelRatio}\n` +
        `aspect ${camera.aspect.toFixed(3)} fov ${camera.fov.toFixed(1)} aim ${aimBlend.toFixed(2)}`;
    }
  }

  // Remote players: create/update meshes, interpolate towards snapshots.
  for (const [id, s] of snapPlayers) {
    if (id === myId) continue;
    if (!s.alive) {
      // Fallen: the figure falls backward onto the ground over FALL_MS
      // and lies there until revival — no name, no effects, just the
      // body. The rifle drops beside it once the body is down. The joints
      // freeze in the pose the figure died in.
      const g = playerMeshes.get(id);
      if (g) {
        const u = g.userData;
        // A fallen body shows no name.
        if (u.headPatch) u.headPatch.visible = false;
        if (u.backPatch) u.backPatch.visible = false;
        // A figure that dies while charging drops the launcher; the rifle
        // is the one that lies beside the body (27/11/2026).
        if (u.launcher) u.launcher.visible = false;
        if (u.rifle) u.rifle.visible = true;
        // Bird's-eye elimination mark (27/11/2026): the disc STAYS at
        // the fall spot, grey, with a white X over it, until the
        // round-end revive restores the team colour. X-ray too.
        // First-person sees only the fallen body (unchanged).
        if (u.floorRing1) u.floorRing1.visible = false;
        if (u.floorRing2) u.floorRing2.visible = false;
        if (u.disc) {
          if (spectating && !ghostMode) {
            u.disc.visible = true;
            u.disc.material.color.set(0x888888);
            u.disc.material.depthTest = false;
            // Keep the disc flat on the ground: the group pitches 90°
            // as it falls, so counter-rotate the disc (and the X).
            u.disc.rotation.x = -Math.PI / 2 - g.rotation.x;
            if (u.elimX) {
              u.elimX.visible = true;
              u.elimX.rotation.x = -Math.PI / 2 - g.rotation.x;
            }
          } else {
            u.disc.visible = false;
            if (u.elimX) u.elimX.visible = false;
          }
        }
        // A fallen body shows no name (28/11/2026, fix-list item 28).
        if (u.discLabel) u.discLabel.visible = false;
        setMeshFade(g, 1); // a body that died mid-climb-fade is fully opaque
        if (u.fallTo !== 1) {
          u.fallFrom = u.fallT ?? 0;
          u.fallTo = 1;
          u.fallStartAt = now;
        }
        const t = Math.min((now - u.fallStartAt) / FALL_MS, 1);
        u.fallT = u.fallFrom + (1 - u.fallFrom) * (t * t); // ease-in: a fall accelerates
        g.rotation.x = u.fallT * (Math.PI / 2);
        if (t >= 1) dropRifle(g);
        g.visible = true;
      }
      continue;
    }
    const g = getPlayerMesh(id);
    g.visible = true;
    const u = g.userData;
    // Stand back up after a fall (round-start revives teleport, so the
    // reset is invisible there). The rifle returns to the hands once the
    // figure is upright. Solo NPCs never stand back up — their snapshot
    // alive flag stays false once down.
    if (u.fallTo !== 0) {
      u.fallFrom = u.fallT ?? 0;
      u.fallTo = 0;
      u.fallStartAt = now;
      // Respawn teleport (27/11/2026): an NPC that respawns (or a player
      // reviving at round start) teleports to a new spot — the snapshot
      // position is metres from the mesh, which still stands at the old
      // spot. The rifle would lie alone at the old spot for the 0.6 s
      // stand-up while the figure stands rifle-less. Hand it back at
      // once; a normal stand-up (same spot) keeps the old timing.
      if (Math.hypot(s.x - g.position.x, s.z - g.position.z) > 3) pickUpRifle(g);
      // Revived (round-end): the bird's-eye elimination mark clears and
      // the team colour returns (27/11/2026).
      if (u.disc) {
        u.disc.material.color.set(TEAM_CSS[u.discRole] || '#ffffff');
        u.disc.rotation.x = -Math.PI / 2;
      }
      if (u.elimX) u.elimX.visible = false;
    }
    if (u.fallT > 0) {
      const t = Math.min((now - u.fallStartAt) / FALL_MS, 1);
      const easeOut = 1 - (1 - t) * (1 - t);
      u.fallT = u.fallFrom * (1 - easeOut);
      g.rotation.x = u.fallT * (Math.PI / 2);
      if (t >= 1) pickUpRifle(g);
    } else {
      g.rotation.x = 0;
    }
    // The on-body name is teammates-only: the enemy team sees no name at all.
    // (Solo players have no team, so they neither show nor see names.)
    // (28/11/2026, fix-list item 28): a spectator is neutral — in
    // spectator mode every player's name shows, not just teammates'.
    const m = meta.get(id) || npcMeta.get(id);
    const isTeammate = !solo && myTeam != null && !!m && !m.solo && m.team === myTeam;
    const showPatch = spectating || isTeammate;
    if (g.userData.headPatch) g.userData.headPatch.visible = showPatch;
    if (g.userData.backPatch) g.userData.backPatch.visible = showPatch;
    // Bird's-eye spectator: a team-coloured disc under each living figure
    // (26/11/2026) — dark figures on the black street are nearly invisible
    // from above without it. Only the spectator's client shows it.
    // Shot flash (27/11/2026): the disc brightens and grows ~1.5x for
    // ~150 ms when its player fires. X-ray (27/11/2026): the disc reads
    // through the roof for an indoor player; the floor shows as extra
    // concentric rings — one per floor above ground. Ghost mode shows
    // none of this: it is a first-person view, not the bird's-eye.
    if (g.userData.disc) {
      const showDisc = spectating && !ghostMode;
      g.userData.disc.visible = showDisc;
      if (showDisc) {
        g.userData.disc.material.depthTest = false;
        const flashing = now < (u.discFlashUntil || 0);
        g.userData.disc.scale.setScalar(flashing ? 1.5 : 1);
        g.userData.disc.material.opacity = flashing ? 1 : 0.75;
        const floor = s.y > 4.5 ? 2 : s.y > 1.5 ? 1 : 0;
        if (u.floorRing1) u.floorRing1.visible = floor >= 1;
        if (u.floorRing2) u.floorRing2.visible = floor >= 2;
      } else {
        if (u.floorRing1) u.floorRing1.visible = false;
        if (u.floorRing2) u.floorRing2.visible = false;
      }
      // Bird's-eye disc name label (28/11/2026, fix-list item 28): the
      // sprite sits just north of the disc (above it on screen) and
      // follows the figure. Same visibility as the disc itself.
      if (g.userData.discLabel) {
        const dl = g.userData.discLabel;
        dl.visible = showDisc && !!g.userData.discLabelName;
        if (dl.visible) dl.position.set(g.position.x, 0.8, g.position.z - 2.5);
      }
    }
    const k = 1 - Math.exp(-dt * 12);
    g.position.x += (s.x - g.position.x) * k;
    g.position.y += (s.y - g.position.y) * k;
    g.position.z += (s.z - g.position.z) * k;
    // Shortest-arc yaw interpolation.
    let dyaw = s.yaw - g.rotation.y;
    while (dyaw > Math.PI) dyaw -= Math.PI * 2;
    while (dyaw < -Math.PI) dyaw += Math.PI * 2;
    g.rotation.y += dyaw * k;
    // Window-climb fade: a figure passing through a window merges with
    // the wall (fades out at the plane, back in on the other side).
    // Purely positional, from the interpolated position — see
    // climbFadeAt in map.js.
    setMeshFade(g, climbFadeAt(g.position.x, g.position.z, curLayout));
    // Pose + walk animation: pick the pose from the snapshot flags, lerp
    // the joints toward it, and swing the legs from the distance actually
    // travelled (interpolated, so teleports and snapshot jitter don't
    // flail them).
    if (u.legL && u.legR) {
      const dx = g.position.x - (u.prevX ?? g.position.x);
      const dz = g.position.z - (u.prevZ ?? g.position.z);
      u.prevX = g.position.x;
      u.prevZ = g.position.z;
      const dist = Math.min(Math.hypot(dx, dz), 0.25);
      const speed = dt > 0 ? dist / dt : 0;
      const moving = speed > 0.4;
      // Crouching reads as a one-knee kneel when still, a low crouch-walk
      // when moving; aiming raises the rifle; otherwise the ready stance.
      // A charging missile soldier fires STANDING with the launcher on
      // the shoulder (27/11/2026, post-v41 item 17 — Lior's drawing),
      // and only kneels when crouching when the shot starts.
      let poseName = 'ready';
      if (s.missile) poseName = s.crouch ? 'missileFire' : 'missileFireStand';
      else if (s.crouch) poseName = moving ? 'crouchWalk' : 'kneel';
      else if (s.aiming) poseName = 'aim';
      // The launcher replaces the rifle in the hands while firing.
      if (u.launcher) u.launcher.visible = !!s.missile;
      if (u.rifle && u.rifle.parent === u.upper) u.rifle.visible = !s.missile;
      const targetAmp = moving ? (s.crouch ? 0.3 : 0.55) : 0;
      u.walkAmp += (targetAmp - u.walkAmp) * (1 - Math.exp(-dt * 8));
      if (moving) u.walkPhase += (dist / 1.1) * Math.PI; // one step per ~1.1 m
      applyPose(g, POSES[poseName], dt, u.walkPhase, u.walkAmp);
    }
  }

  // Window climb button: visible only while alive in-game near a
  // ground-floor window.
  currentWindow = ((game.phase === 'playing' || solo) && myAlive) ? nearbyWindow() : null;
  climbBtn.classList.toggle('hidden', !currentWindow || climbing);

  // YOU'RE DOWN expiry: after 3 seconds, switch to spectate (round still
  // going) or show the held round/match-end UI (round ended during the 3s).
  if (downUntil && now >= downUntil) {
    downUntil = 0;
    downOverlay.classList.add('hidden');
    if (pendingRoundEnd) {
      const msg = pendingRoundEnd;
      pendingRoundEnd = null;
      showRoundEndUI(msg);
    }
    if (pendingMatchEnd) {
      const msg = pendingMatchEnd;
      pendingMatchEnd = null;
      showMatchEndUI(msg);
    }
    if (game.phase === 'playing' && !myAlive) {
      spectateTarget = livingTeammates()[0] ?? null;
    }
  }

  if (spectating) {
    // Bird's-eye admin view: the height is computed from the current
    // layout's bounds so the whole map fits end to end (item 25) —
    // figures read as small dots. Drag pans the view along the
    // street. The look deltas are consumed here so they never leak
    // into the yaw when spectating ends.
    // Ghost mode (27/11/2026): the camera sits at a living player's eyes
    // and looks where they look, plus the admin's own look offset — the
    // ghost sees and is not seen. REC keeps recording either way: it
    // captures the canvas stream, and the toggle never stops it.
    const look = controls.takeLook();
    if (ghostMode && ghostTarget != null) {
      const t = snapPlayers.get(ghostTarget);
      if (t && t.alive) {
        ghostYawOff -= look.dx * 0.0023;
        ghostPitchOff -= look.dy * 0.0023;
        ghostPitchOff = Math.max(-1.45, Math.min(1.45, ghostPitchOff));
        camera.position.set(t.x, t.y + EYE_HEIGHT, t.z);
        camera.rotation.set(t.pitch + ghostPitchOff, t.yaw + ghostYawOff, 0);
        // Hide the followed player's mesh — the ghost looks through
        // their eyes; their own body would fill the screen. The
        // remote-player loop re-shows it next frame when the ghost
        // leaves or the target changes.
        const g = playerMeshes.get(ghostTarget);
        if (g) g.visible = false;
      } else {
        // Target died or left: follow the next living player, or fall
        // back to bird's-eye when nobody is left.
        ghostTarget = firstLivingPlayer();
        if (ghostTarget == null) {
          specX = Math.max(curLayout.bounds.x0, Math.min(curLayout.bounds.x1, specX - look.dx * 0.05));
          specZ = Math.max(curLayout.bounds.z0, Math.min(curLayout.bounds.z1, specZ - look.dy * 0.05));
          camera.position.set(specX, birdEyeHeight(), specZ);
          camera.rotation.set(-Math.PI / 2, 0, 0);
        }
      }
    } else {
      specX = Math.max(curLayout.bounds.x0, Math.min(curLayout.bounds.x1, specX - look.dx * 0.05));
      specZ = Math.max(curLayout.bounds.z0, Math.min(curLayout.bounds.z1, specZ - look.dy * 0.05));
      camera.position.set(specX, birdEyeHeight(), specZ);
      camera.rotation.set(-Math.PI / 2, 0, 0);
    }
  } else if ((game.phase === 'playing' || solo) && myAlive) {
    // Crouch blends the eye height down smoothly (no snap on toggle).
    // The eye follows the real crouch state only: the missile firing
    // stance is standing unless crouching (27/11/2026, item 17), so
    // charging no longer drops the eye to kneel height on its own —
    // the v41 kneel drop is gone with the kneel pose.
    const wantCrouch = controls.crouch;
    crouchBlend += ((wantCrouch ? 1 : 0) - crouchBlend) * (1 - Math.exp(-dt * 10));
    // Look still works mid-climb (the camera crosses the wall with the
    // player); movement, fire and reload are frozen (see below, tryFire,
    // tryReload). The look deltas are consumed either way.
    const look = controls.takeLook();
    local.yaw -= look.dx * 0.0023;
    local.pitch -= look.dy * 0.0023;
    local.pitch = Math.max(-1.45, Math.min(1.45, local.pitch));

    // Move — or, mid-climb, the scripted crossing: 1.5 s from climbFrom
    // to climbTo with no collision (the path crosses the wall by design).
    if (climbing) {
      const t = Math.min((now - climbStartAt) / CLIMB_MS, 1);
      const s = t * t * (3 - 2 * t); // smoothstep: slow ends, fastest mid-wall
      local.x = climbFrom.x + (climbTo.x - climbFrom.x) * s;
      local.z = climbFrom.z + (climbTo.z - climbFrom.z) * s;
      if (t >= 1) climbing = false;
    } else {
      const move = controls.getMove();
      const sin = Math.sin(local.yaw);
      const cos = Math.cos(local.yaw);
      const fx = -sin;
      const fz = -cos;
      const rx = cos;
      const rz = -sin;
      let vx = fx * move.z + rx * move.x;
      let vz = fz * move.z + rz * move.x;
      // Defense prep time (Lior, 25/11/2026): attackers wait at spawn
      // while the defenders get into position — no movement, but looking
      // around still works (yaw is applied below, outside this block).
      if (game.prepActive && meta.get(myId)?.role === 'attackers') { vx = 0; vz = 0; }
      const len = Math.hypot(vx, vz);
      if (len > 0) {
        // Aiming down the sights slows movement; crouching slows it more.
        const speed = SPEED * (1 - aimBlend * 0.35) * (controls.crouch ? 0.45 : 1) * Math.min(1, len);
        vx = (vx / len) * speed;
        vz = (vz / len) * speed;
      }
      // Crouch-walk limit: 2 continuous seconds of walking while crouched
      // returns the player to standing (Lior, 25/11/2026).
      if (controls.crouch && len > 0.01) {
        crouchWalkMs += dt * 1000;
        if (crouchWalkMs >= CROUCH_WALK_LIMIT_MS) {
          controls.setCrouch(false);
          crouchWalkMs = 0;
        }
      } else {
        crouchWalkMs = 0;
      }
      let nx = local.x + vx * dt;
      let nz = local.z + vz * dt;
      const resolved = resolveCollision(nx, nz, local.y, undefined, curLayout);
      nx = resolved.x;
      nz = resolved.z;
      local.x = nx;
      local.z = nz;
      local.y = floorHeightAt(nx, nz, local.y, curLayout);
    }

    camera.position.set(local.x, local.y + EYE_HEIGHT - crouchBlend * CROUCH_EYE_DROP, local.z);
    camera.rotation.set(local.pitch, local.yaw, 0);

    // Semi-auto: one shot per press, never a held-down stream.
    if (firePressed) tryFire(now);

    // Send movement ~15/sec. The stance flags ride along so other players
    // see the pose (kneel / aim); aiming uses the smoothed ADS blend so a
    // half-second ADS flicker doesn't flap the pose.
    if (now - lastMoveSent >= MOVE_SEND_MS) {
      lastMoveSent = now;
      socket.send({ t: 'move', x: local.x, y: local.y, z: local.z, yaw: local.yaw, pitch: local.pitch,
        aiming: aimBlend > 0.5, crouch: controls.crouch });
    }
  } else if (myAlive === false && downUntil) {
    // YOU'RE DOWN: frozen first-person view at the death spot, no input.
    // Takes precedence over the spectate and elevated views.
    camera.position.set(local.x, local.y + EYE_HEIGHT - crouchBlend * CROUCH_EYE_DROP, local.z);
    camera.rotation.set(local.pitch, local.yaw, 0);
  } else if (game.phase === 'playing' && myAlive === false) {
    // Spectate: chase camera behind a living teammate.
    const target = spectateTarget != null ? snapPlayers.get(spectateTarget) : null;
    if (target) {
      const backX = Math.sin(target.yaw);
      const backZ = Math.cos(target.yaw);
      camera.position.set(target.x + backX * 4.5, target.y + 2.6, target.z + backZ * 4.5);
      camera.lookAt(target.x, target.y + 1.4, target.z);
    } else {
      camera.position.set(0, 40, 0);
      camera.lookAt(0, 0, 0);
    }
  } else {
    // Lobby / intermission / ended: elevated view of the street.
    camera.position.set(0, 42, -20);
    camera.lookAt(0, 0, 10);
  }

  // A mid-climb death or round end cancels the climb (the position stays
  // where it is — the next round's spawn resets it). Runs outside the
  // movement block so a mid-climb death still clears the flag.
  if (climbing && !(myAlive && (game.phase === 'playing' || solo))) climbing = false;

  // Blast visuals: expand to the 4 m radius and fade over 0.6 s.
  for (let i = activeExplosions.length - 1; i >= 0; i--) {
    const e = activeExplosions[i];
    const age = now - e.bornAt;
    if (age >= 600) {
      scene.remove(e.mesh);
      e.mesh.geometry.dispose();
      e.mesh.material.dispose();
      activeExplosions.splice(i, 1);
    } else {
      const t = age / 600;
      e.mesh.scale.setScalar(0.3 + t * 3.7);
      e.mesh.material.opacity = 0.85 * (1 - t);
    }
  }

  updateMissileCross();
  updateShotMarkings(now);
  updateHUD();
  updateViewmodel(dt, now);

  renderer.render(scene, camera);
}

// ---------------------------------------------------------------------------
// Boot
// ---------------------------------------------------------------------------
window.__tacticalBooted = true;
window.__tacticalLocal = local; // debug/test hook: the local player's position
// Debug/test hook: the firing-relevant state (why a click did or did not fire).
window.__tacticalFire = () => ({
  queued: controls.fireQueued,
  locked: controls.locked,
  alive: myAlive,
  solo,
  phase: game.phase,
  inMag: myInMag,
  reloading,
  climbing,
  mapOpen,
});
// Debug/test hook: the rendered map name (27/11/2026, corrected item 8 —
// verifies solo renders the map the admin picked on the join screen).
window.__tacticalMap = () => currentMapName;
// Debug/test hook: the first-person viewmodel state (27/11/2026, item 15 —
// the launcher must stay hidden until the first munition press).
window.__tacticalViewmodel = () => ({
  myClass,
  launcherVisible: launcherViewmodel ? launcherViewmodel.visible : null,
  rifleVisible: rifle ? rifle.visible : null,
  missileCharging: !!missileCharging,
  missileFiredAt,
});
window.__tacticalMeshes = playerMeshes; // debug/test hook: remote player meshes by id
document.getElementById('boot')?.remove(); // inline splash done its job
socket.connect();
// If the server never answers, say so instead of hanging silently.
setTimeout(() => {
  if (!connected && connectStatus.textContent.startsWith('Connecting')) {
    connectStatus.textContent = 'Cannot reach the game server. Is the "npm start" window still open? If yes, reload this page.';
    connectStatus.style.color = '#ff8080';
  }
}, 5000);
